});

test("start と書いた Box は start として読まれる", () => {
  expect(BoxAlign.fromProps({ align: "start" })).toBe("start");
});

test("center と書いた Box は center として読まれる", () => {
  expect(BoxAlign.fromProps({ align: "center" })).toBe("center");
});

