test("右辺の帯を後ろの兄弟の右辺の近くまで運ぶと、兄弟の右辺に揃う幅が通知される", () => {
  const onResize = vi.fn();
  renderCanvas({ selection: setupSelection(), onResize });
  drawnStacked();
  const card = drawnAt("card", CardBounds);

  // 右辺が 338 まで来る量。寄せが無ければ幅は 238
  pressPointer(card, { x: 298, y: 140 });
  movePointer(card, { x: 336, y: 140 });
  releasePointer(card, { x: 336, y: 140 });

  expect(onResize).toHaveBeenLastCalledWith(
    ResizeEdit.create([{ axis: "width", length: 240 }]),
    expect.anything(),
  );
});

test("右下の角を同じだけ運ぶと、兄弟の右辺には吸い付かない", () => {
  const onResize = vi.fn();
  renderCanvas({ selection: setupSelection(), onResize });
  drawnStacked();
  const card = drawnAt("card", CardBounds);

  pressPointer(card, { x: 298, y: 178 });
  movePointer(card, { x: 336, y: 178 });
  releasePointer(card, { x: 336, y: 178 });

  expect(onResize).toHaveBeenLastCalledWith(
    ResizeEdit.create([
      { axis: "width", length: 238 },
      { axis: "height", length: 80 },
    ]),
    expect.anything(),
  );
});

test("右辺の帯を後ろの兄弟の右辺の近くまで運んでいる間、兄弟の右辺に線が 1 本出る", () => {
  renderCanvas({ selection: setupSelection() });
  drawnStacked();
  const card = drawnAt("card", CardBounds);

  pressPointer(card, { x: 298, y: 140 });
  movePointer(card, { x: 336, y: 140 });

  // `footer` の右辺に中心を合わせ、`card` の上辺 100 から `footer` の下辺 220 までをまたぐ
  expect(snapGuides()).toHaveLength(1);
  expect(snapGuides()[0].getAttribute("style")).toContain(
    "left: 339px; top: 100px; width: 2px; height: 120px",
  );
});

export type ResizeSnapTargets =
  /** artboard と、回っていない `placement: "absolute"` のノード。どの掴み方でも効く。 */
  | Readonly<{ kind: "anyGrip"; names: readonly string[] }>
  /** 条件（`flowSnapTargets`）を満たすフロー配置のノード。`axis` の 1 軸だけを掴んだときに効く。 */
  | Readonly<{ kind: "axisOnly"; axis: Axis; names: readonly string[] }>
  /** 回っている・掴めない・条件を満たさないフロー配置のノード。 */
  | Readonly<{ kind: "none" }>;

namesFor(targets: ResizeSnapTargets, grip: ResizeGrip): readonly string[] {
  switch (targets.kind) {
    case "anyGrip":
      return targets.names;
    case "axisOnly":
      return grabsOnly(grip, targets.axis) ? targets.names : [];
    case "none":
      return [];
  }
},

export const BoxAligns = {
  Start: "start",
  Center: "center",
  End: "end",
  Stretch: "stretch",
} as const;

/** Box が交差軸のどこへ子を揃えるか。 */
export type BoxAlign = ValueOf<typeof BoxAligns>;

stillCrossAxis(props: ResolvedProps<"Box">): Option<Axis> {
  const placesAtCrossStart =
    !Wrap.isWrapping(Wrap.fromProps(props)) &&
    BoxAlign.isStartForFixedChild(BoxAlign.fromProps(props));
  if (!placesAtCrossStart) {
    return Option.none;
  }
  return Option.flatMap(BoxElement.childDirection(props), (direction) => {
    const crossAxis = CssDirection.crossAxis(direction);
    return Option.map(
      Size.fixedLengthFromProps(props, crossAxis),
      () => crossAxis,
    );
  });
},

const axis = Option.flatMap(
  DesignDocument.boxPropsOf(document, parentName),
  BoxElement.stillCrossAxis,
);
const names = parentWithSiblingNames(document, { name, parentName });
const hasSnapTargets = Option.isSome(axis) && Option.isSome(names);
if (!hasSnapTargets) {
  return ResizeSnapTargets.None;
}
return { kind: "axisOnly", axis: axis.value, names: names.value };

hold(
  resizable: ResizableSelection,
  grip: ResizeGrip,
  pointerOrigin: Offset,
): ResizeHold {
  return {
    grip,
    pointerOrigin,
    grabbedAt: resizable.origin,
    rotation: resizable.rotation,
    snapTargetNames: ResizeSnapTargets.namesFor(resizable.snapTargets, grip),
    snapFrom: Option.none,
  };
},

function grabsOnly(grip: ResizeGrip, axis: Axis): boolean {
  const grabs = ResizeGrip.grabs(grip);
  return grabs.length === 1 && grabs[0].length.axis === axis;
}

/**
 * 子が交差軸の長さを変えても、子の始点・親・兄弟の位置が動かない軸。答えは `declarations`
 * が出す CSS とブラウザの既定値で決まり、主軸を答えない理由とあわせて docs/06-ui.md
 * 「リサイズハンドル」の辺のスナップにある。
 *
 * @param props デフォルト解決済みの Box の props
 * @returns 子の交差軸。子を並べない（`layout: free`）・折り返す・揃えが center / end・
 *   交差軸の長さが決まっていない（hug / fill / `fixed` なのに長さが無い）ときは `none`
 */
stillCrossAxis(props: ResolvedProps<"Box">): Option<Axis> {
  const placesAtCrossStart =
    !Wrap.isWrapping(Wrap.fromProps(props)) &&
    BoxAlign.isStartForFixedChild(BoxAlign.fromProps(props));
  if (!placesAtCrossStart) {
    return Option.none;
  }
  return Option.flatMap(BoxElement.childDirection(props), (direction) => {
    const crossAxis = CssDirection.crossAxis(direction);
    return Option.map(
      Size.fixedLengthFromProps(props, crossAxis),
      () => crossAxis,
    );
  });
},
